<template><div class="page-container"><div class="page-head"><div><h2 class="page-title">运维中心</h2><p class="page-subtitle">同步任务、凭据健康和操作审计</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="同步任务" name="tasks"><el-table :data="tasks" stripe><el-table-column prop="sync_type" label="类型"/><el-table-column prop="status" label="状态"/><el-table-column label="结果"><template #default="{row}">{{row.success_count}} / {{row.total_count}}</template></el-table-column><el-table-column prop="error_message" label="错误" show-overflow-tooltip/><el-table-column prop="created_at" label="创建时间"/></el-table></el-tab-pane><el-tab-pane label="凭据健康" name="credentials"><el-table :data="credentials" stripe><el-table-column prop="meta_account_id" label="BM"/><el-table-column prop="token_type" label="类型"/><el-table-column prop="health" label="健康状态"/><el-table-column prop="expires_at" label="过期时间"/><el-table-column prop="last_error" label="最近错误" show-overflow-tooltip/></el-table></el-tab-pane><el-tab-pane label="操作审计" name="audit"><el-table :data="audits" stripe><el-table-column prop="action" label="操作"/><el-table-column prop="resource_type" label="资源类型"/><el-table-column prop="resource_id" label="资源 ID"/><el-table-column prop="user_id" label="操作人"/><el-table-column prop="created_at" label="时间"/></el-table></el-tab-pane></el-tabs></div></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { operationsApi } from '@/api/admin'
const tab = ref('tasks'); const loading = ref(false); const tasks = ref<any[]>([]); const credentials = ref<any[]>([]); const audits = ref<any[]>([])
async function load() { loading.value = true; try { if (tab.value === 'tasks') tasks.value = (await operationsApi.syncTasks()).data; if (tab.value === 'credentials') credentials.value = (await operationsApi.credentialHealth()).data; if (tab.value === 'audit') audits.value = (await operationsApi.auditLogs()).data } finally { loading.value = false } }
onMounted(load)
</script>
